from collections import defaultdict

def solve_2sat(n={{n}}, clauses={{clauses}}):
    g = defaultdict(list); gr = defaultdict(list)
    def var(x): return 2*abs(x) + (0 if x > 0 else 1)
    def neg(v): return v ^ 1
    for a, b in clauses:
        g[neg(var(a))].append(var(b))
        g[neg(var(b))].append(var(a))
        gr[var(b)].append(neg(var(a)))
        gr[var(a)].append(neg(var(b)))
    V = 2*(n+1); visited = [False]*V; order = []
    def dfs1(u):
        stack = [(u, iter(g[u]))]
        visited[u] = True
        while stack:
            x, it = stack[-1]
            for w in it:
                if not visited[w]: visited[w] = True; stack.append((w, iter(g[w]))); break
            else:
                order.append(x); stack.pop()
    for v in range(V):
        if not visited[v]: dfs1(v)
    comp = [-1]*V; c = 0
    for v in reversed(order):
        if comp[v] != -1: continue
        stack = [v]; comp[v] = c
        while stack:
            x = stack.pop()
            for w in gr[x]:
                if comp[w] == -1: comp[w] = c; stack.append(w)
        c += 1
    assign = {}
    for i in range(1, n+1):
        if comp[2*i] == comp[2*i+1]: return None
        assign[i] = comp[2*i] > comp[2*i+1]
    return assign
